import 'package:cloud_firestore/cloud_firestore.dart';
import 'package:firebase_auth/firebase_auth.dart';
import 'package:flutter/material.dart';
import 'windows_desktop_shell.dart';

class WindowsEditProfileScreen extends StatefulWidget {
  const WindowsEditProfileScreen({super.key});
  @override State<WindowsEditProfileScreen> createState()=>_WindowsEditProfileScreenState();
}
class _WindowsEditProfileScreenState extends State<WindowsEditProfileScreen> {
  final _form=GlobalKey<FormState>();
  final _name=TextEditingController(),_phone=TextEditingController(),_degrees=TextEditingController(),_address=TextEditingController(),_court=TextEditingController();
  static const _types=['Junior','Senior','Corporate','Independent'];
  String _type='Junior'; bool _loading=true,_saving=false;
  @override void initState(){super.initState();_load();}
  @override void dispose(){for(final c in [_name,_phone,_degrees,_address,_court]){c.dispose();}super.dispose();}
  Future<void> _load() async {
    final uid=FirebaseAuth.instance.currentUser?.uid;
    if(uid==null){if(mounted)setState(()=>_loading=false);return;}
    try{final snap=await FirebaseFirestore.instance.collection('users').doc(uid).get();final data=snap.data()??<String,dynamic>{};if(!mounted)return;setState((){_name.text=data['name'] as String? ?? '';_phone.text=data['phone'] as String? ?? '';_degrees.text=data['degrees'] as String? ?? '';_address.text=data['address'] as String? ?? data['officeAddress'] as String? ?? '';_court.text=data['courtAddress'] as String? ?? '';final loaded=data['advocateType'] as String?;if(_types.contains(loaded))_type=loaded!;_loading=false;});}catch(_){if(mounted)setState(()=>_loading=false);}
  }
