    Row(children:[IconButton(onPressed:()=>Navigator.of(context).pop(),icon:const Icon(Icons.arrow_back_rounded)),const SizedBox(width:8),const Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('ACCOUNT IDENTITY',style:TextStyle(color:WindowsDesktopShell.muted,fontSize:10,fontWeight:FontWeight.w800,letterSpacing:1.4)),SizedBox(height:6),Text('Edit professional profile',style:TextStyle(fontFamily:'Georgia',color:WindowsDesktopShell.forest,fontSize:27,fontWeight:FontWeight.w700))])),if(_saving)const CircularProgressIndicator(color:WindowsDesktopShell.forest)else FilledButton.icon(onPressed:_save,icon:const Icon(Icons.save_outlined),label:const Text('Save changes'),style:FilledButton.styleFrom(backgroundColor:WindowsDesktopShell.forest,padding:const EdgeInsets.symmetric(horizontal:17,vertical:15)))]),
    const SizedBox(height:8),const Text('These fields update your existing LED user profile and identity-directory entry.',style:TextStyle(color:WindowsDesktopShell.muted,fontSize:12)),const SizedBox(height:22),
    if(_loading)const Expanded(child:Center(child:CircularProgressIndicator(color:WindowsDesktopShell.forest))) else Expanded(child:Form(key:_form,child:LayoutBuilder(builder:(context,constraints){final wide=constraints.maxWidth>720;final identity=Column(children:[_field('Full name *',_name,'Your professional name'),_field('Phone number',_phone,'Contact phone',isRequired:false),_field('Qualifications / degrees',_degrees,'Qualifications',required:false)]);final office=Column(children:[_field('Office / chamber address',_address,'Office or chamber address',required:false,maxLines:3),_field('Court address',_court,'Court address',required:false,maxLines:3),_dropdown()]);return SingleChildScrollView(child:wide?Row(crossAxisAlignment:CrossAxisAlignment.start,children:[Expanded(child:_panel('Personal & professional details',identity)),const SizedBox(width:16),Expanded(child:_panel('Practice & location',office))]):Column(children:[_panel('Personal & professional details',identity),const SizedBox(height:14),_panel('Practice & location',office)]));}))),
  ]))))),
  Widget _panel(String title,Widget child)=>Container(width:double.infinity,padding:const EdgeInsets.all(20),decoration:BoxDecoration(color:Colors.white,borderRadius:BorderRadius.circular(14),border:Border.all(color:WindowsDesktopShell.border)),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(title,style:const TextStyle(color:WindowsDesktopShell.ink,fontSize:14,fontWeight:FontWeight.w800)),const SizedBox(height:16),child]));
