  Widget _dropdown()=>Padding(padding:const EdgeInsets.only(bottom:13),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Text('Advocate type',style:TextStyle(color:WindowsDesktopShell.ink,fontSize:11,fontWeight:FontWeight.w700)),const SizedBox(height:7),DropdownButtonFormField<String>(value:_type,decoration:InputDecoration(filled:true,fillColor:WindowsDesktopShell.canvas,border:OutlineInputBorder(borderRadius:BorderRadius.circular(10),borderSide:const BorderSide(color:WindowsDesktopShell.border))),items:_types.map((t)=>DropdownMenuItem(value:t,child:Text(t))).toList(),onChanged:(v){if(v!=null)setState(()=>_type=v);})]));
  Future<void> _save() async {if(!_form.currentState!.validate())return;final uid=FirebaseAuth.instance.currentUser?.uid;if(uid==null){ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Please sign in again.')));return;}setState(()=>_saving=true);try{final db=FirebaseFirestore.instance;final ref=db.collection('users').doc(uid);final snap=await ref.get();final existing=snap.data()??<String,dynamic>{};final ledId=existing['ledId'] as String?;final batch=db.batch();batch.set(ref,{'name':_name.text.trim(),'phone':_phone.text.trim(),'degrees':_degrees.text.trim(),'address':_address.text.trim(),'officeAddress':_address.text.trim(),'courtAddress':_court.text.trim(),'advocateType':_type,'updatedAt':FieldValue.serverTimestamp()},SetOptions(merge:true));if(ledId!=null&&ledId.trim().isNotEmpty){batch.set(db.collection('led_id_directory').doc(ledId.trim()),{'uid':uid,'ledId':ledId.trim(),'name':_name.text.trim(),'advocateType':_type,'profileCompleted':existing['profileCompleted']==true,'updatedAt':FieldValue.serverTimestamp()},SetOptions(merge:true));}await batch.commit();if(mounted){ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Profile updated successfully.')));Navigator.of(context).pop();}}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('Could not update profile: $e')));}finally{if(mounted)setState(()=>_saving=false);}}
}